import type { VideoTrack } from "@paraxe/core";
export interface Film01Credit {
  id: string;
  role: string;
  name: string;
}
export interface Film01Viewing {
  id: string;
  label: string;
  detail: string;
  href?: string;
}
export interface Film01Frame {
  id: string;
  label: string;
  caption: string;
  src?: string;
  alt?: string;
  art?: "passage" | "shore" | "light";
}
export interface Film01Props {
  studio?: string;
  studioHref?: string;
  eyebrow?: string;
  title?: string;
  tagline?: string;
  year?: string;
  duration?: string;
  language?: string;
  genre?: string;
  posterSrc?: string;
  posterAlt?: string;
  imageCredit?: string;
  storyTitle?: string;
  paragraphs?: readonly string[];
  quote?: string;
  quoteAttribution?: string;
  trailerSrc?: string;
  trailerPoster?: string;
  trailerTracks?: readonly VideoTrack[];
  trailerDescription?: string;
  frames?: readonly Film01Frame[];
  credits?: readonly Film01Credit[];
  viewings?: readonly Film01Viewing[];
  pressHref?: string;
  notice?: string;
}
export const sampleFrames: readonly Film01Frame[] = [
  {
    id: "departure",
    label: "THE DEPARTURE",
    caption: "The places we leave behind.",
    art: "passage",
  },
  {
    id: "return",
    label: "THE RETURN",
    caption: "A familiar shore. A different person.",
    art: "shore",
  },
  {
    id: "between",
    label: "THE IN-BETWEEN",
    caption: "Something worth staying for.",
    art: "light",
  },
];
export const sampleParagraphs = [
  "On the last night before leaving home, a sound recordist returns to the coast where she grew up. An unexpected encounter turns a familiar journey into something she cannot quite put into words.",
  "A story about the things we carry, the places that hold them, and the small moments that ask us to stay a little longer.",
] as const;
export const sampleCredits: readonly Film01Credit[] = [
  { id: "director", role: "Written & directed by", name: "Alex Morgan" },
  { id: "cast", role: "Featuring", name: "Jamie Ellis / Robin Vale" },
  { id: "camera", role: "Cinematography", name: "Taylor Reed" },
  { id: "sound", role: "Original score", name: "Casey Lane" },
];
export const sampleViewings: readonly Film01Viewing[] = [
  {
    id: "cinema",
    label: "On the big screen",
    detail: "Screening dates to be announced",
  },
  {
    id: "online",
    label: "From wherever you are",
    detail: "Online release to be announced",
  },
];
export function validateFilm(
  credits: readonly Film01Credit[],
  viewings: readonly Film01Viewing[],
  frames: readonly Film01Frame[] = [],
) {
  for (const items of [credits, viewings, frames]) {
    const ids = new Set<string>();
    for (const item of items) {
      if (!/^[a-zA-Z0-9][a-zA-Z0-9_-]*$/.test(item.id) || ids.has(item.id))
        throw new RangeError("Film items require unique anchor-safe IDs.");
      ids.add(item.id);
    }
  }
}

.film01 {
  --film01-section-gap: var(--space-12);
  --film01-column-gap: var(--space-10);
  --film01-scene-ink: color-mix(
    in oklch,
    var(--background-primary) 88%,
    var(--text-primary)
  );
  --film01-scene-light: var(--text-primary);
  --film01-scene-tint: var(--brand-primary);
  padding: var(--space-6) var(--container-padding-lg) var(--space-8);
  background: var(--background-primary);
  color: var(--text-primary);
  font-family: var(--font-family-body);
}
.film01 *,
.film01 *::before,
.film01 *::after {
  box-sizing: border-box;
}
.film01 :is(h1, h2, h3, p, dl, dd, blockquote, figure) {
  margin: 0;
}
.film01-inner {
  max-width: var(--container-max-width);
  margin-inline: auto;
}
.film01 a {
  color: inherit;
  text-underline-offset: var(--space-1);
}
.film01 a:focus-visible {
  outline: var(--focus-ring-width) solid var(--focus-ring-color);
  outline-offset: var(--focus-ring-offset);
}
.film01 :is(header, section) {
  scroll-margin-block-start: var(--space-7);
}
.film01 .film01-masthead {
  gap: var(--space-5);
  padding-block-end: var(--space-5);
  border-block-end: var(--border-width-thin) solid var(--border-default);
}
.film01-brand {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
  font-family: var(--font-family-display);
  font-size: var(--font-size-lg);
  text-decoration: none;
  letter-spacing: var(--letter-spacing-tight);
}
.film01-brand span {
  color: var(--text-muted);
  font-size: var(--typography-micro-size);
  font-family: var(--font-family-mono);
  letter-spacing: var(--letter-spacing-wide);
}
.film01-masthead nav {
  font-size: var(--typography-caption-size);
}
.film01-masthead nav .flex {
  gap: var(--space-6);
}
.film01-masthead nav a {
  text-decoration: none;
}
.film01-masthead nav a:hover {
  text-decoration: underline;
}
.film01-kicker {
  color: var(--text-muted);
  font-family: var(--font-family-mono);
  font-size: var(--typography-micro-size);
  letter-spacing: var(--letter-spacing-wide);
}
.film01-hero {
  display: flex;
  align-items: center;
  gap: var(--film01-column-gap);
  padding-block: var(--space-8) var(--space-10);
}
.film01-hero-copy {
  flex: 1 1 57%;
  min-width: 0;
  padding-block: var(--space-6);
}
.film01 .film01-hero-copy > .film01-kicker {
  color: var(--brand-primary);
}
.film01 .film01-hero-copy h1 {
  margin-block: var(--space-6);
  font-size: var(--typography-hero-size);
  letter-spacing: var(--letter-spacing-tighter);
  line-height: var(--typography-heading-lineheight);
  white-space: pre-line;
  text-transform: uppercase;
  overflow-wrap: anywhere;
}
.film01 .film01-hero-copy > p:not(.film01-kicker) {
  max-width: var(--content-width-narrow);
  color: var(--text-secondary);
  font-size: var(--typography-lead-size);
  line-height: var(--line-height-relaxed);
}
.film01-hero-bottom {
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  gap: var(--space-7);
  margin-block-start: var(--space-9);
}
.film01-byline {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  color: var(--text-muted);
  font-size: var(--typography-caption-size);
}
.film01-byline strong {
  color: var(--text-primary);
  font-weight: var(--font-weight-medium);
}
.film01 .film01-action {
  gap: var(--space-7);
  text-decoration: none;
  color: var(--button-secondary-text);
}
.film01 .film01-action.btn-primary {
  color: var(--button-primary-text);
}
.film01-poster-frame {
  flex: 0 1 39%;
  min-width: 0;
  padding: var(--space-3);
  border: var(--border-width-thin) solid var(--border-default);
  background: var(--surface-base);
  border-radius: var(--media-radius);
  box-shadow: var(--shadow-lg);
  transform: rotate(2deg);
}
.film01-poster-art {
  position: relative;
  aspect-ratio: var(--media-aspect-portrait);
  overflow: hidden;
  border-radius: var(--radius-sm);
}
.film01-poster-art > .media,
.film01-poster-art img {
  width: 100%;
  height: 100%;
}
.film01-poster-overprint {
  position: absolute;
  inset: var(--space-4);
  display: flex;
  justify-content: space-between;
  align-items: start;
  gap: var(--space-3);
  color: var(--film01-scene-light);
  font-size: var(--typography-micro-size);
  font-family: var(--font-family-mono);
  letter-spacing: var(--letter-spacing-wide);
  text-transform: uppercase;
  pointer-events: none;
}
.film01-poster-overprint > span:last-child {
  text-align: end;
}
.film01-poster-frame figcaption {
  display: flex;
  justify-content: space-between;
  gap: var(--space-3);
  padding-block-start: var(--space-3);
  color: var(--text-muted);
  font-family: var(--font-family-mono);
  font-size: var(--typography-micro-size);
  letter-spacing: var(--letter-spacing-wide);
}
.film01-facts {
  display: flex;
  gap: var(--space-6);
  padding-block: var(--space-5);
  border-block: var(--border-width-thin) solid var(--border-default);
}
.film01-facts > div {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}
.film01-facts dt {
  color: var(--text-muted);
  font-size: var(--typography-micro-size);
  text-transform: uppercase;
  letter-spacing: var(--letter-spacing-wide);
}
.film01-facts dd {
  font-size: var(--font-size-sm);
}
/* A perspective-built duotone concept illustration. All ink comes from tokens. */
.film01-scene {
  position: absolute;
  inset: 0;
  overflow: hidden;
  background: var(--film01-scene-ink);
}
.film01-scene > div {
  position: absolute;
}
.film01-scene-distance {
  inset: 0;
  background: linear-gradient(
    175deg,
    color-mix(in oklch, var(--film01-scene-ink) 60%, var(--film01-scene-tint)),
    color-mix(in oklch, var(--film01-scene-light) 60%, var(--film01-scene-tint))
      58%,
    var(--film01-scene-ink)
  );
}
.film01-scene-water {
  inset-inline: 0;
  top: 52%;
  height: 26%;
  background: repeating-linear-gradient(
    176deg,
    transparent,
    transparent var(--space-1),
    color-mix(in oklch, var(--film01-scene-light) 25%, transparent)
      calc(var(--space-1) + var(--border-width-thin)),
    transparent var(--space-2)
  );
  opacity: 0.6;
}
.film01-scene-wall-left {
  inset: 0 auto 0 0;
  width: 48%;
  background: linear-gradient(
    110deg,
    var(--film01-scene-ink) 25%,
    color-mix(in oklch, var(--film01-scene-light) 12%, var(--film01-scene-ink))
  );
  clip-path: polygon(0 0, 100% 0, 72% 78%, 0 100%);
}
.film01-scene-wall-right {
  inset: 0 0 0 auto;
  width: 32%;
  background: linear-gradient(
    270deg,
    var(--film01-scene-ink),
    color-mix(in oklch, var(--film01-scene-light) 16%, var(--film01-scene-ink))
  );
  clip-path: polygon(48% 0, 100% 0, 100% 100%, 0 78%);
}
.film01-scene-lintel {
  inset: 0 0 auto;
  height: 28%;
  background: var(--film01-scene-ink);
  clip-path: polygon(0 0, 100% 0, 100% 65%, 42% 100%, 0 72%);
}
.film01-scene-floor {
  inset: auto 0 0;
  height: 28%;
  background: linear-gradient(
    var(--film01-scene-ink),
    color-mix(in oklch, var(--film01-scene-light) 12%, var(--film01-scene-ink))
  );
  clip-path: polygon(34% 0, 68% 0, 100% 100%, 0 100%);
}
.film01-scene-reflection {
  bottom: 0;
  left: 39%;
  width: 34%;
  height: 28%;
  clip-path: polygon(38% 0, 62% 0, 100% 100%, 0 100%);
  background: linear-gradient(
    color-mix(in oklch, var(--film01-scene-light) 45%, transparent),
    transparent
  );
}
.film01-scene-person {
  top: 61%;
  left: 54%;
  width: 3.5%;
  height: 15%;
}
.film01-scene-person::before {
  content: "";
  position: absolute;
  top: 0;
  left: 34%;
  width: 36%;
  height: 18%;
  background: var(--film01-scene-ink);
  border-radius: var(--radius-full);
}
.film01-scene-person::after {
  content: "";
  position: absolute;
  inset: 18% 0 0;
  background: var(--film01-scene-ink);
  clip-path: polygon(
    28% 0,
    70% 0,
    100% 48%,
    78% 54%,
    72% 100%,
    53% 100%,
    48% 65%,
    42% 100%,
    22% 100%,
    23% 53%,
    0 48%
  );
}
.film01-scene-shadow {
  top: 75%;
  left: 54%;
  width: 8%;
  height: 25%;
  transform: skew(-22deg);
  transform-origin: top;
  background: linear-gradient(var(--film01-scene-ink), transparent);
}
.film01-scene-grain {
  inset: 0;
  opacity: 0.16;
  background: repeating-linear-gradient(
    0deg,
    transparent,
    transparent var(--border-width-thin),
    var(--film01-scene-ink) var(--space-1)
  );
  pointer-events: none;
}
.film01-scene-shore .film01-scene-wall,
.film01-scene-shore .film01-scene-lintel {
  display: none;
}
.film01-scene-shore .film01-scene-water {
  top: 45%;
  height: 55%;
}
.film01-scene-shore .film01-scene-distance {
  background: linear-gradient(
    175deg,
    var(--film01-scene-ink),
    color-mix(in oklch, var(--film01-scene-light) 55%, var(--film01-scene-tint))
      50%,
    var(--film01-scene-ink) 51%
  );
}
.film01-scene-shore .film01-scene-floor {
  left: -40%;
  width: 120%;
  height: 20%;
}
.film01-scene-shore .film01-scene-person {
  left: 70%;
  top: 62%;
  height: 17%;
}
.film01-scene-shore .film01-scene-shadow {
  left: 70%;
  top: 78%;
}
.film01-scene-shore .film01-scene-reflection {
  left: 10%;
  width: 60%;
  height: 52%;
  opacity: 0.25;
}
.film01-scene-light .film01-scene-wall-left {
  width: 72%;
}
.film01-scene-light .film01-scene-wall-right {
  width: 28%;
}
.film01-scene-light .film01-scene-person,
.film01-scene-light .film01-scene-shadow {
  display: none;
}
.film01-scene-light .film01-scene-reflection {
  left: 58%;
  width: 9%;
  height: 65%;
}
.film01-scene-light .film01-scene-distance {
  background: linear-gradient(
    100deg,
    var(--film01-scene-ink) 30%,
    var(--film01-scene-tint),
    var(--film01-scene-light)
  );
}
.film01-story {
  display: flex;
  gap: var(--film01-column-gap);
  padding-block: var(--film01-section-gap);
}
.film01-story > div:first-child {
  flex: 1 1 42%;
  min-width: 0;
}
.film01-story-body {
  flex: 1 1 58%;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: var(--space-5);
}
.film01 .film01-story h2,
.film01 .film01-watch h2 {
  margin-block-start: var(--space-5);
  font-size: var(--website-title-size);
  line-height: var(--typography-heading-lineheight);
  white-space: pre-line;
  overflow-wrap: anywhere;
}
.film01-story-body > p {
  color: var(--text-secondary);
  font-size: var(--font-size-base);
  line-height: var(--line-height-relaxed);
  max-width: var(--content-width-readable);
}
.film01 blockquote {
  padding-block-start: var(--space-5);
  border-block-start: var(--border-width-thin) solid var(--border-default);
}
.film01 blockquote p {
  font-family: var(--font-family-display);
  font-size: var(--font-size-xl);
  line-height: var(--line-height-relaxed);
}
.film01 blockquote footer {
  margin-block-start: var(--space-3);
  color: var(--text-muted);
  font-size: var(--typography-caption-size);
}
.film01 .film01-section-heading {
  gap: var(--space-5);
  margin-block-end: var(--space-6);
}
.film01-section-heading h2 {
  font-size: var(--font-size-2xl);
  line-height: var(--typography-heading-lineheight);
}
.film01-section-heading .film01-kicker + h2 {
  margin-block-start: var(--space-3);
}
.film01-section-heading > p:not(.film01-kicker) {
  max-width: var(--content-width-narrow);
  color: var(--text-muted);
  font-size: var(--typography-caption-size);
}
.film01-frames {
  padding-block-end: var(--film01-section-gap);
}
.film01-contact-sheet {
  display: flex;
  gap: var(--space-4);
}
.film01-contact-sheet figure {
  flex: 1;
  min-width: 0;
}
.film01-contact-sheet figure:first-child {
  flex: 1.4;
}
.film01-still {
  position: relative;
  overflow: hidden;
  height: calc(var(--space-4) * 13);
  border-radius: var(--media-radius);
  background: var(--surface-base);
}
.film01-still .media,
.film01-still img {
  width: 100%;
  height: 100%;
}
.film01-contact-sheet figcaption {
  padding-block-start: var(--space-4);
}
.film01-contact-sheet figcaption > span {
  font-family: var(--font-family-mono);
  font-size: var(--typography-micro-size);
  letter-spacing: var(--letter-spacing-wide);
  color: var(--text-muted);
}
.film01-contact-sheet figcaption p {
  font-size: var(--typography-caption-size);
  margin-block-start: var(--space-2);
}
.film01-trailer {
  padding-block-end: var(--film01-section-gap);
}
.film01-trailer .video {
  border-radius: var(--media-radius);
}
.film01-media-note {
  padding-block-start: var(--space-3);
  color: var(--text-muted);
  font-size: var(--typography-caption-size);
}
.film01-credits {
  padding-block: var(--space-7);
  border-block: var(--border-width-thin) solid var(--border-default);
}
.film01-credits .film01-section-heading h2 {
  font-size: var(--font-size-xl);
}
.film01-credit-list {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-6);
}
.film01-credit-list > div {
  flex: 1 1 20%;
  min-width: 0;
}
.film01-credit-list dt {
  color: var(--text-muted);
  font-size: var(--typography-micro-size);
}
.film01-credit-list dd {
  margin-block-start: var(--space-2);
  font-size: var(--font-size-base);
  overflow-wrap: anywhere;
}
.film01-watch {
  display: flex;
  gap: var(--film01-column-gap);
  padding-block: var(--film01-section-gap);
}
.film01-watch > div:first-child {
  flex: 1 1 42%;
  min-width: 0;
}
.film01-viewings {
  flex: 1 1 58%;
  min-width: 0;
}
.film01-viewings article {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--space-5);
  padding-block: var(--space-6);
  border-block-end: var(--border-width-thin) solid var(--border-default);
}
.film01-viewings article:first-child {
  padding-block-start: 0;
}
.film01-viewings article h3 {
  font-size: var(--font-size-xl);
}
.film01-viewings article p {
  color: var(--text-muted);
  font-size: var(--typography-caption-size);
  margin-block-start: var(--space-2);
}
.film01-release-mark {
  font-family: var(--font-family-display);
  font-size: var(--font-size-3xl);
  color: var(--border-strong);
}
.film01-viewings article > a {
  flex-shrink: 0;
}
.film01 .film01-footer {
  gap: var(--space-6);
  border-block-start: var(--border-width-thin) solid var(--border-default);
  padding-block-start: var(--space-6);
  font-size: var(--typography-caption-size);
}
.film01-footer p {
  max-width: var(--content-width-readable);
  color: var(--text-muted);
  font-size: var(--typography-micro-size);
  margin-block-start: var(--space-3);
}
@media (max-width: 900px) {
  .film01 {
    padding-inline: var(--container-padding);
    --film01-column-gap: var(--space-6);
    --film01-section-gap: var(--space-9);
  }
  .film01-hero {
    gap: var(--space-5);
  }
  .film01 .film01-hero-copy h1 {
    font-size: min(
      var(--typography-hero-size),
      calc(var(--font-size-6xl) * 1.15)
    );
  }
  .film01-hero-bottom {
    flex-direction: column;
    align-items: start;
    gap: var(--space-5);
  }
  .film01-poster-frame {
    flex-basis: 42%;
  }
  .film01-still {
    height: calc(var(--space-4) * 10);
  }
  .film01-credit-list > div {
    flex-basis: 40%;
  }
}
@media (max-width: 600px) {
  .film01 .film01-masthead {
    align-items: start;
  }
  .film01-masthead nav .flex {
    gap: var(--space-4);
  }
  .film01-hero {
    flex-direction: column;
    align-items: stretch;
    padding-block: var(--space-6) var(--space-8);
    gap: var(--space-7);
  }
  .film01-hero-copy {
    padding-block: 0;
  }
  .film01 .film01-hero-copy h1 {
    font-size: var(--typography-hero-size);
  }
  .film01-hero-bottom {
    flex-direction: row;
    align-items: end;
    justify-content: space-between;
    margin-block-start: var(--space-6);
  }
  .film01-poster-frame {
    flex-basis: auto;
    width: 85%;
    align-self: center;
  }
  .film01-facts {
    flex-wrap: wrap;
  }
  .film01-facts > div {
    flex-basis: 40%;
  }
  .film01-story,
  .film01-watch {
    flex-direction: column;
    gap: var(--space-6);
  }
  .film01-contact-sheet {
    flex-direction: column;
    gap: var(--space-6);
  }
  .film01-still {
    height: calc(var(--space-4) * 13);
  }
  .film01-viewings article {
    flex-direction: column;
    align-items: start;
  }
  .film01-credit-list > div {
    flex-basis: 100%;
  }
}

import type { Film01Frame } from "../shared/film";
export function FilmArtwork({
  variant = "passage",
}: {
  variant?: Film01Frame["art"];
}) {
  return (
    <div className={`film01-scene film01-scene-${variant}`} aria-hidden="true">
      <div className="film01-scene-distance" />
      <div className="film01-scene-water" />
      <div className="film01-scene-wall film01-scene-wall-left" />
